ALTER TABLE User ADD COLUMN department VARCHAR(160) NULL, ADD COLUMN position VARCHAR(160) NULL;
ALTER TABLE UserInvitation ADD COLUMN revokedAt DATETIME(3) NULL, ADD COLUMN status VARCHAR(30) NOT NULL DEFAULT 'pending', ADD COLUMN deliveryStatus VARCHAR(30) NOT NULL DEFAULT 'not_requested', ADD COLUMN deliveryAttempts INTEGER NOT NULL DEFAULT 0, ADD COLUMN sentAt DATETIME(3) NULL, ADD COLUMN deliveryUpdatedAt DATETIME(3) NULL, ADD COLUMN noteEncrypted TEXT NULL;
UPDATE UserInvitation SET status='accepted' WHERE consumedAt IS NOT NULL;
CREATE TABLE StaffPasswordReset (id VARCHAR(191) NOT NULL, userId VARCHAR(191) NOT NULL, tokenHash CHAR(64) NOT NULL, expiresAt DATETIME(3) NOT NULL, consumedAt DATETIME(3) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX StaffPasswordReset_tokenHash_key(tokenHash), INDEX StaffPasswordReset_userId_expiresAt_idx(userId,expiresAt), PRIMARY KEY(id), CONSTRAINT StaffPasswordReset_userId_fkey FOREIGN KEY(userId) REFERENCES User(id) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE MfaRecoveryCode (id VARCHAR(191) NOT NULL, userId VARCHAR(191) NOT NULL, codeHash CHAR(64) NOT NULL, usedAt DATETIME(3) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX MfaRecoveryCode_codeHash_key(codeHash), INDEX MfaRecoveryCode_userId_usedAt_idx(userId,usedAt), PRIMARY KEY(id), CONSTRAINT MfaRecoveryCode_userId_fkey FOREIGN KEY(userId) REFERENCES User(id) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
